/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - Vpotula
/// Contract class for <c>METAMEXCustFreeTextInvService</c> class.
/// </summary>
[DataContractAttribute]
class METAMEXCustFreeTextInvContract
{
    private     JournalId           journalId;
    private     METAMEXBatchId      batchId;
    private     DataAreaId          dataArea;
    private     List                companyCustList      = new List(Types::Container);
    private int                     tasks;
    private METAMEXProcessFTI       processAdhocFTI;


  
}

