{
    processAdhocFTI = _processAdhocFTI;
    return processAdhocFTI;
}

[DataMemberAttribute]
public JournalId parmJournalId(JournalId _journalId = journalId)
{
    journalId = _journalId;
    return journalId;
}

[DataMemberAttribute]
public METAMEXBatchId parmBatchId(METAMEXBatchId _batchId = batchId)
{
    batchId = _batchId;
    return batchId;
}

[
    DataMemberAttribute('Company')
]
public DataAreaId parmDataArea(DataAreaId _dataArea = dataArea)
{
    dataArea = _dataArea;
    return dataArea;
}

[DataMemberAttribute('CustomerCompanyList'),
 SysOperationControlVisibilityAttribute(false),
